const fs = require('fs');

const input = $input.first().json;

const KB_PATH = '/files/knowledge/base-conocimiento-maiclinic.json';

if (!fs.existsSync(KB_PATH)) {
  throw new Error(`No se encuentra la base de conocimiento en: ${KB_PATH}`);
}

const raw = fs.readFileSync(KB_PATH, 'utf8');
const base = JSON.parse(raw);

const mensajeUsuario = input.text || '';

function normalizar(texto) {
  return String(texto || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const consultaNormalizada = normalizar(mensajeUsuario);

const stopwords = new Set([
  'hola', 'buenas', 'buenos', 'dias', 'tardes', 'noches',
  'quiero', 'queria', 'saber', 'puedo', 'puedes', 'podrias',
  'podriais', 'podeis', 'podéis', 'teneis', 'tenéis',
  'tengo', 'sobre', 'para', 'como', 'cuando', 'cuanto',
  'cuánto', 'donde', 'dónde', 'este', 'esta', 'esto',
  'esas', 'esos', 'una', 'unos', 'unas', 'con', 'por',
  'que', 'qué', 'del', 'las', 'los', 'hay', 'soy',
  'me', 'mi', 'en', 'el', 'la', 'de', 'y', 'o',
  'un', 'al', 'lo', 'se', 'su', 'sus', 'mas', 'más',
  'pasar', 'dar', 'dais', 'mandar', 'enviar',
  'informacion', 'información', 'info', 'algo', 'poco',
  'favor', 'gracias'
]);

const palabras = consultaNormalizada
  .split(' ')
  .filter(p => p.length > 2 && !stopwords.has(p));

const sinonimos = {
  tratamiento: ['tratamientos', 'servicios', 'tecnicas', 'medicina estetica', 'ginecologia regenerativa'],
  tratamientos: ['tratamiento', 'servicios', 'tecnicas', 'medicina estetica', 'ginecologia regenerativa'],
  servicio: ['servicios', 'tratamientos', 'tecnicas', 'medicina estetica', 'ginecologia regenerativa'],
  servicios: ['servicio', 'tratamientos', 'tecnicas', 'medicina estetica', 'ginecologia regenerativa'],
  tecnica: ['tecnicas', 'tratamientos'],
  tecnicas: ['tecnica', 'tratamientos'],

  estetica: ['medicina estetica', 'facial', 'armonizacion', 'full face', 'antiarrugas', 'labios', 'ojeras'],
  facial: ['medicina estetica', 'armonizacion facial', 'full face', 'antiarrugas'],
  faciales: ['medicina estetica', 'facial', 'armonizacion facial', 'full face', 'antiarrugas'],
  cara: ['facial', 'armonizacion facial', 'full face'],
  rostro: ['facial', 'armonizacion facial', 'full face'],

  armonizacion: ['armonizacion facial', 'full face', 'relleno', 'volumen'],
  full: ['full face', 'armonizacion facial'],
  face: ['full face', 'armonizacion facial'],

  bioestimulacion: ['bioestimulacion de colageno', 'colageno', 'inductores de colageno'],
  bioestimuladores: ['bioestimulacion', 'inductores de colageno', 'colageno'],
  colageno: ['bioestimulacion de colageno', 'inductores de colageno'],
  inductores: ['inductores de colageno', 'bioestimulacion de colageno'],

  polinucleotidos: ['regeneracion piel', 'calidad de piel', 'bioestimulacion'],
  piel: ['polinucleotidos', 'bioestimulacion', 'inductores de colageno'],

  botox: ['neuromoduladores', 'toxina botulinica', 'antiarrugas', 'tercio superior', 'bruxismo', 'sonrisa gingival'],
  toxina: ['botox', 'neuromoduladores'],
  neuromoduladores: ['botox', 'toxina botulinica', 'antiarrugas', 'tercio superior', 'bruxismo', 'sonrisa gingival'],

  antiarrugas: ['tercio superior', 'neuromoduladores', 'botox'],
  arrugas: ['antiarrugas', 'tercio superior', 'neuromoduladores'],
  frente: ['tercio superior', 'antiarrugas', 'neuromoduladores'],
  entrecejo: ['tercio superior', 'antiarrugas', 'neuromoduladores'],
  patas: ['patas de gallo', 'tercio superior', 'antiarrugas'],
  gallo: ['patas de gallo', 'tercio superior', 'antiarrugas'],

  sonrisa: ['sonrisa gingival', 'neuromoduladores'],
  gingival: ['sonrisa gingival', 'neuromoduladores'],

  bruxismo: ['masetero', 'neuromoduladores', 'mandibula'],
  masetero: ['bruxismo', 'neuromoduladores'],
  mandibula: ['bruxismo', 'masetero'],

  labios: ['acido hialuronico', 'zona peribucal', 'relleno labios'],
  labio: ['labios', 'zona peribucal', 'relleno labios'],
  peribucal: ['labios', 'codigo de barras', 'acido hialuronico'],
  ojeras: ['mirada', 'acido hialuronico'],

  sudor: ['hiperhidrosis', 'neuromoduladores'],
  sudoracion: ['hiperhidrosis', 'neuromoduladores'],
  hiperhidrosis: ['sudoracion excesiva', 'neuromoduladores'],

  ginecologia: ['ginecologia regenerativa', 'zona intima', 'vaginal'],
  vaginal: ['ginecologia regenerativa', 'zona intima'],
  vulvar: ['ginecologia regenerativa', 'zona intima'],
  intima: ['ginecologia regenerativa', 'vaginal', 'vulvar'],

  sequedad: ['atrofia', 'hidratacion', 'lubricacion', 'menopausia', 'acido hialuronico vaginal'],
  seca: ['sequedad', 'atrofia', 'lubricacion'],
  lubricacion: ['sequedad', 'hidratacion'],
  atrofia: ['sequedad', 'menopausia', 'rejuvenecimiento vaginal'],

  pis: ['orina', 'incontinencia', 'urinaria'],
  orina: ['pis', 'incontinencia', 'urinaria'],
  urinaria: ['orina', 'incontinencia'],
  perdida: ['incontinencia', 'orina'],
  perdidas: ['incontinencia', 'orina'],
  escape: ['incontinencia', 'orina'],
  escapes: ['incontinencia', 'orina'],

  relaciones: ['dispareunia', 'dolor', 'sexual', 'vaginismo'],
  sexo: ['relaciones', 'dispareunia', 'dolor', 'sexual'],
  sexual: ['relaciones', 'sexo', 'dispareunia'],
  dolor: ['dispareunia', 'vulvodinia', 'vaginismo'],

  menopausia: ['sofocos', 'hormonal', 'sequedad', 'atrofia', 'tratamiento hormonal'],
  sofocos: ['menopausia', 'hormonal'],
  hormonal: ['menopausia', 'terapia hormonal', 'modulacion hormonal'],

  laser: ['láser', 'co2', 'ginecologico'],
  radiofrecuencia: ['regenerativa', 'vaginal', 'vulvar'],
  prp: ['plasma', 'plaquetas'],
  plasma: ['prp', 'plaquetas'],
  exosomas: ['regeneracion', 'regenerativa'],
  ondas: ['ondas de choque', 'dolor pelvico', 'regeneracion'],
  liquen: ['escleroso', 'vulvar', 'picor'],
  picor: ['liquen', 'escozor', 'irritacion'],
  infecciones: ['candidiasis', 'vaginosis', 'repeticion'],
  postparto: ['cicatrices', 'recuperacion post parto', 'suelo pelvico'],

  precio: ['cuesta', 'coste', 'presupuesto', 'valoracion'],
  precios: ['cuesta', 'coste', 'presupuesto', 'valoracion'],
  cuesta: ['precio', 'coste', 'presupuesto'],
  coste: ['precio', 'cuesta', 'presupuesto'],
  presupuesto: ['precio', 'coste', 'valoracion'],

  cita: ['consulta', 'telefono', 'email', 'direccion'],
  consulta: ['cita', 'telefono', 'email', 'direccion'],
  ubicacion: ['direccion', 'clinica', 'valencia'],
  direccion: ['ubicacion', 'clinica', 'valencia'],
  telefono: ['contacto', 'cita', 'consulta'],
  email: ['contacto', 'cita', 'consulta']
};

const terminosBusqueda = new Set(palabras);

for (const palabra of palabras) {
  if (sinonimos[palabra]) {
    sinonimos[palabra].forEach(s => terminosBusqueda.add(normalizar(s)));
  }
}

function textoItem(item) {
  const faqs = (item.faqs || [])
    .map(f => `${f.question || ''} ${f.answer || ''}`)
    .join('\n');

  const headings = (item.content?.headings || [])
    .map(h => h.text || '')
    .join('\n');

  const paragraphs = (item.content?.paragraphs || [])
    .join('\n');

  return `
    ${item.sourceFile || ''}
    ${item.url || ''}
    ${item.title || ''}
    ${item.ogTitle || ''}
    ${item.metaDescription || ''}
    ${item.ogDescription || ''}
    ${item.treatment?.name || ''}
    ${item.treatment?.category || ''}
    ${headings}
    ${paragraphs}
    ${item.content?.fullText || ''}
    ${faqs}
  `;
}

function obtenerClinica() {
  return base.find(i => i.clinic)?.clinic || {};
}

function obtenerHorarios(clinic) {
  return (clinic.openingHours || [])
    .map(h => {
      const dias = Array.isArray(h.dayOfWeek)
        ? h.dayOfWeek.join(', ')
        : h.dayOfWeek;

      return `${dias}: ${h.opens} - ${h.closes}`;
    })
    .join('\n');
}

function esPaginaUtil(item) {
  const nombre = normalizar(item.treatment?.name || '');
  const titulo = normalizar(item.title || '');
  const source = normalizar(item.sourceFile || '');

  if (!item.treatment?.name && !item.treatment?.category) return false;
  if (nombre.includes('page has moved')) return false;
  if (titulo.includes('page has moved')) return false;
  if (source.includes('equipo medico')) return false;

  return true;
}

function esPaginaPrincipal(item) {
  const source = normalizar(item.sourceFile || '');

  return (
    source === 'index html' ||
    source === 'medicina estetica index html' ||
    source === 'ginecologia regenerativa index html'
  );
}

function esMedicinaEstetica(item) {
  return (
    normalizar(item.treatment?.category || '').includes('medicina estetica') ||
    normalizar(item.sourceFile || '').includes('medicina estetica')
  );
}

function esGinecologiaRegenerativa(item) {
  return (
    normalizar(item.treatment?.category || '').includes('ginecologia regenerativa') ||
    normalizar(item.sourceFile || '').includes('ginecologia regenerativa')
  );
}

function construirContexto(items, limiteTexto = 800) {
  return items.map((item, index) => {
    const headings = (item.content?.headings || [])
      .map(h => `- ${h.text || ''}`)
      .filter(Boolean)
      .join('\n');

    const paragraphs = (item.content?.paragraphs || [])
      .filter(Boolean)
      .join('\n');

    const fullText = item.content?.fullText || '';

    const faqs = (item.faqs || [])
      .slice(0, 4)
      .map(f => `P: ${f.question || ''}\nR: ${f.answer || ''}`)
      .join('\n');

    const textoBase = [
      headings ? `Apartados y tratamientos detectados:\n${headings}` : '',
      fullText ? `Contenido:\n${fullText}` : '',
      paragraphs ? `Texto adicional:\n${paragraphs}` : '',
      faqs ? `Preguntas frecuentes:\n${faqs}` : ''
    ]
      .filter(Boolean)
      .join('\n\n');

    return `
FUENTE ${index + 1}
Título: ${item.title || ''}
Tratamiento: ${item.treatment?.name || ''}
Categoría: ${item.treatment?.category || ''}
URL: ${item.url || ''}

Información relevante:
${textoBase.slice(0, limiteTexto)}
`;
  }).join('\n\n---\n\n');
}

function crearRespuesta(items, debugExtra = {}, opciones = {}) {
  const clinic = obtenerClinica();
  const horarios = obtenerHorarios(clinic);

  const limiteTexto = opciones.limiteTexto || 800;

  return [
    {
      json: {
        ...input,

        contexto_base: construirContexto(items, limiteTexto),
        resultados_encontrados: items.length,

        clinic_name: clinic.name || 'MAI CLINIC',
        clinic_phone: clinic.telephone || '',
        clinic_email: clinic.email || '',
        clinic_address: clinic.address
          ? `${clinic.address.street}, ${clinic.address.postalCode} ${clinic.address.city}`
          : '',
        clinic_opening_hours: horarios,

        debug_busqueda: {
          mensaje_original: mensajeUsuario,
          consulta_normalizada: consultaNormalizada,
          palabras_detectadas: palabras,
          terminos_busqueda: Array.from(terminosBusqueda),
          resultados: items.map(item => ({
            title: item.title || '',
            treatment: item.treatment?.name || '',
            category: item.treatment?.category || '',
            sourceFile: item.sourceFile || '',
            url: item.url || ''
          })),
          ...debugExtra
        }
      }
    }
  ];
}

/**
 * 1. Consultas de contacto, cita, dirección u horarios.
 */
const palabrasContacto = new Set([
  'cita',
  'citas',
  'telefono',
  'teléfono',
  'contacto',
  'contactar',
  'direccion',
  'dirección',
  'ubicacion',
  'ubicación',
  'horario',
  'horarios',
  'email',
  'correo',
  'donde',
  'dónde'
]);

const esConsultaContacto = palabras.some(p => palabrasContacto.has(p));

if (esConsultaContacto) {
  const paginasContacto = base
    .filter(item => item.clinic)
    .slice(0, 1);

  if (paginasContacto.length > 0) {
    return crearRespuesta(paginasContacto, {
      tipo_busqueda: 'consulta_contacto'
    });
  }
}

/**
 * 2. Detectar consulta facial concreta.
 */
const consultaEsFacialConcreta =
  consultaNormalizada.includes('facial') ||
  consultaNormalizada.includes('faciales') ||
  consultaNormalizada.includes('rostro') ||
  consultaNormalizada.includes('cara') ||
  consultaNormalizada.includes('labios') ||
  consultaNormalizada.includes('bruxismo') ||
  consultaNormalizada.includes('arrugas') ||
  consultaNormalizada.includes('antiarrugas') ||
  consultaNormalizada.includes('armonizacion') ||
  consultaNormalizada.includes('bioestimulacion') ||
  consultaNormalizada.includes('polinucleotidos') ||
  consultaNormalizada.includes('neuromoduladores') ||
  consultaNormalizada.includes('botox') ||
  consultaNormalizada.includes('sonrisa gingival') ||
  consultaNormalizada.includes('hiperhidrosis') ||
  consultaNormalizada.includes('medicina estetica');

/**
 * 3. NUEVO BLOQUE IMPORTANTE:
 * Si pregunta por tratamientos faciales o medicina estética, usamos un resumen exclusivo
 * y no dejamos que entre en el resumen general de ginecología.
 */
const esConsultaGeneralFacial =
  consultaEsFacialConcreta &&
  (
    consultaNormalizada.includes('tratamientos') ||
    consultaNormalizada.includes('tratamiento') ||
    consultaNormalizada.includes('servicios') ||
    consultaNormalizada.includes('servicio') ||
    consultaNormalizada.includes('informacion') ||
    consultaNormalizada.includes('información') ||
    consultaNormalizada.includes('info') ||
    consultaNormalizada.includes('que teneis') ||
    consultaNormalizada.includes('que tenéis') ||
    consultaNormalizada.includes('que ofreceis') ||
    consultaNormalizada.includes('que ofrecéis') ||
    consultaNormalizada.includes('exactamente')
  );

if (esConsultaGeneralFacial) {
  const clinic = obtenerClinica();
  const horarios = obtenerHorarios(clinic);

  const resumenFacial = `
RESUMEN EXCLUSIVO DE TRATAMIENTOS FACIALES / MEDICINA ESTÉTICA DE MAI CLINIC

El usuario pregunta por tratamientos faciales o medicina estética facial.

Tratamientos faciales disponibles:
- Armonización facial o full face.
- Bioestimulación de colágeno.
- Polinucleótidos.
- Inductores de colágeno.
- Neuromoduladores.
- Tratamiento antiarrugas del tercio superior.
- Sonrisa gingival.
- Tratamiento de labios y zona peribucal.
- Tratamiento de bruxismo.
- Hiperhidrosis.

INSTRUCCIÓN OBLIGATORIA:
Responde SOLO sobre medicina estética/facial.
NO menciones ginecología regenerativa.
NO menciones incontinencia, menopausia, sequedad vaginal ni tratamientos íntimos.
Si el usuario pide información general, lista estos tratamientos de forma breve y ofrece valoración personalizada.
`;

  return [
    {
      json: {
        ...input,

        contexto_base: resumenFacial,
        resultados_encontrados: 10,

        clinic_name: clinic.name || 'MAI CLINIC',
        clinic_phone: clinic.telephone || '',
        clinic_email: clinic.email || '',
        clinic_address: clinic.address
          ? `${clinic.address.street}, ${clinic.address.postalCode} ${clinic.address.city}`
          : '',
        clinic_opening_hours: horarios,

        debug_busqueda: {
          mensaje_original: mensajeUsuario,
          consulta_normalizada: consultaNormalizada,
          palabras_detectadas: palabras,
          terminos_busqueda: Array.from(terminosBusqueda),
          tipo_busqueda: 'consulta_general_facial_resumen_exclusivo'
        }
      }
    }
  ];
}

/**
 * 4. Consultas generales sobre tratamientos o servicios.
 * Si era facial concreta, NO entra aquí.
 */
const patronesConsultaGeneral = [
  'tratamientos',
  'tratamiento',
  'servicios',
  'servicio',
  'que ofrece',
  'que ofreceis',
  'que ofrecéis',
  'que ofrecen',
  'que teneis',
  'que tenéis',
  'que haceis',
  'que hacéis',
  'especialidades',
  'informacion general',
  'información general',
  'info general',
  'informacion de tratamientos',
  'información de tratamientos',
  'info de tratamientos'
];

const palabrasConsultaGeneral = new Set([
  'tratamiento',
  'tratamientos',
  'servicio',
  'servicios',
  'ofrece',
  'ofrecen',
  'ofreceis',
  'ofrecéis',
  'ofrecemos',
  'especialidad',
  'especialidades',
  'tecnicas',
  'técnicas',
  'opciones'
]);

const esConsultaGeneralTratamientos =
  !consultaEsFacialConcreta &&
  (
    patronesConsultaGeneral.some(p => consultaNormalizada.includes(normalizar(p))) ||
    palabras.some(p => palabrasConsultaGeneral.has(p))
  );

if (esConsultaGeneralTratamientos) {
  const clinic = obtenerClinica();
  const horarios = obtenerHorarios(clinic);

  const resumenGeneralTratamientos = `
RESUMEN GENERAL DE TRATAMIENTOS DE MAI CLINIC

MAI Clinic trabaja principalmente dos áreas:

1. Medicina estética:
Armonización facial o full face, bioestimulación de colágeno, polinucleótidos, inductores de colágeno, neuromoduladores, tratamiento antiarrugas del tercio superior, sonrisa gingival, tratamiento de labios y zona peribucal, bruxismo e hiperhidrosis.

2. Ginecología regenerativa:
Láser ginecológico, radiofrecuencia vaginal y vulvar, PRP vaginal, ácido hialurónico vaginal, exosomas, ondas de choque, incontinencia de orina, menopausia, recuperación posparto, disfunciones sexuales, liquen escleroso, infecciones vaginales de repetición y rejuvenecimiento vaginal.

INSTRUCCIÓN PARA LA RESPUESTA:
Responde en máximo 5 líneas.
No listes todos los tratamientos uno por uno.
Agrupa por áreas.
Termina recomendando una valoración personalizada.
`;

  return [
    {
      json: {
        ...input,

        contexto_base: resumenGeneralTratamientos,
        resultados_encontrados: 2,

        clinic_name: clinic.name || 'MAI CLINIC',
        clinic_phone: clinic.telephone || '',
        clinic_email: clinic.email || '',
        clinic_address: clinic.address
          ? `${clinic.address.street}, ${clinic.address.postalCode} ${clinic.address.city}`
          : '',
        clinic_opening_hours: horarios,

        debug_busqueda: {
          mensaje_original: mensajeUsuario,
          consulta_normalizada: consultaNormalizada,
          palabras_detectadas: palabras,
          terminos_busqueda: Array.from(terminosBusqueda),
          tipo_busqueda: 'consulta_general_resumen_compacto'
        }
      }
    }
  ];
}

/**
 * 5. Detección de intención por área.
 */
const terminosMedicinaEstetica = [
  'estetica', 'facial', 'faciales', 'cara', 'rostro', 'armonizacion', 'full face',
  'bioestimulacion', 'colageno', 'inductores', 'polinucleotidos',
  'botox', 'toxina', 'neuromoduladores', 'antiarrugas', 'arrugas',
  'tercio superior', 'frente', 'entrecejo', 'patas de gallo',
  'sonrisa gingival', 'bruxismo', 'masetero', 'labios', 'labio',
  'peribucal', 'ojeras', 'hiperhidrosis', 'sudor'
];

const terminosGinecologia = [
  'ginecologia', 'vaginal', 'vagina', 'vulvar', 'vulva', 'intima',
  'sequedad', 'lubricacion', 'atrofia', 'menopausia', 'sofocos',
  'incontinencia', 'orina', 'pis', 'relaciones', 'sexo', 'sexual',
  'vaginismo', 'vulvodinia', 'liquen', 'picor', 'infecciones',
  'postparto', 'parto', 'laser ginecologico', 'radiofrecuencia vaginal',
  'prp vaginal', 'ondas de choque'
];

const consultaEsMedicinaEstetica = terminosMedicinaEstetica.some(t =>
  consultaNormalizada.includes(normalizar(t))
);

const consultaEsGinecologia = terminosGinecologia.some(t =>
  consultaNormalizada.includes(normalizar(t))
);

/**
 * 6. Búsqueda normal por relevancia.
 */
const resultados = base
  .filter(esPaginaUtil)
  .map(item => {
    const titulo = normalizar(`
      ${item.title || ''}
      ${item.treatment?.name || ''}
      ${item.treatment?.category || ''}
      ${item.sourceFile || ''}
    `);

    const completo = normalizar(textoItem(item));

    const faqs = normalizar(
      (item.faqs || [])
        .map(f => `${f.question || ''} ${f.answer || ''}`)
        .join(' ')
    );

    let score = 0;

    for (const termino of terminosBusqueda) {
      if (!termino) continue;

      if (titulo.includes(termino)) score += 12;
      if (faqs.includes(termino)) score += 7;
      if (completo.includes(termino)) score += 3;
    }

    if (consultaEsMedicinaEstetica && esMedicinaEstetica(item)) score += 12;
    if (consultaEsMedicinaEstetica && esGinecologiaRegenerativa(item)) score -= 8;

    if (consultaEsGinecologia && esGinecologiaRegenerativa(item)) score += 12;
    if (consultaEsGinecologia && esMedicinaEstetica(item)) score -= 8;

    const preguntaPorSequedad =
      consultaNormalizada.includes('sequedad') ||
      consultaNormalizada.includes('seca') ||
      consultaNormalizada.includes('lubricacion') ||
      consultaNormalizada.includes('atrofia');

    const itemSequedad =
      titulo.includes('sequedad') ||
      titulo.includes('hialuronico vaginal') ||
      titulo.includes('acido hialuronico vaginal');

    if (!preguntaPorSequedad && itemSequedad) {
      score -= 8;
    }

    if (esPaginaPrincipal(item)) {
      score -= 4;
    }

    return {
      score,
      item
    };
  })
  .filter(r => r.score > 0)
  .sort((a, b) => b.score - a.score)
  .slice(0, 4);

